cd /workspace && LD_LIBRARY_PATH=/workspace/native python3 - << 'EOF'
import sys, random, itertools, traceback
sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/workspace/.deps')
import numpy as np
import te.engine as eng

orig = eng._face_solve
def patched(H, b, dv, slot_com, idx, tidx, n, m):
    for k in tidx:
        if not any(slot_com[s] == k for s in idx):
            print('SINGULAR STATE: commodity', k, 'in T with no free slot')
            print(' idx', idx, 'tidx', tidx, 'slot_com', slot_com, 'dv', dv, 'mode?')
            raise SystemExit(1)
    return orig(H, b, dv, slot_com, idx, tidx, n, m)
eng._face_solve = patched

rng = random.Random(3)
for it in range(4000):
    n = rng.randint(1, 6); m = rng.randint(1, 3)
    slot_com = np.array([rng.randrange(m) for _ in range(n)], dtype=np.int64)
    for k in range(m):
        if not np.any(slot_com == k):
            slot_com[rng.randrange(n)] = k
    E = rng.randint(1, 5)
    col = np.zeros((n, E))
    for s in range(n):
        for e in range(E):
            if rng.random() < 0.4: col[s, e] = 1.0 / rng.randint(1, 4)
    rho = rng.randint(1, 8)
    H = np.eye(n) + rho*(col@col.T)
    B = np.array([rng.uniform(-3,3) for _ in range(E)])
    b = -rho*(col@B)
    mode = rng.choice(['route','admit'])
    if mode=='admit': b = b-1.0
    dv = np.array([rng.randint(1,5) for _ in range(m)], dtype=np.float64)
    try:
        eng._active_set_solve(H, b, dv, slot_com, m, mode)
    except SystemExit:
        print('at trial', it, 'mode', mode)
        break
    except Exception as e:
        print('trial', it, 'mode', mode, 'ERR', e)
        print('slot_com', slot_com, 'dv', dv)
        break
else:
    print('no failure in 4000')
EOF
